module ring_counter (
    input        clk,
    input        reset,
    output [7:0] out
);

    reg [2:0] pos;  // 3 bits to represent values 0 to 7

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pos <= 3'd0;
        end else begin
            pos <= pos + 3'd1;
        end
    end

    // One-hot output generated by left shifting 1 by the position index
    assign out = 8'b00000001 << pos;

endmodule